{
  "name": "openqwencode",
  "version": "0.1.8",
  "description": "OpenCode plugin for Qwen OAuth login and free Qwen Code models",
  "author": "Daltonganger",
  "type": "module",
  "main": "./index.js",
  "files": [
    "index.js",
    "plugin.js",
    "link.js",
    "events.js",
    "README.md"
  ],
  "exports": {
    ".": "./index.js",
    "./plugin": "./plugin.js",
    "./link": "./link.js",
    "./events": "./events.js"
  },
  "bin": {
    "openqwencode": "link.js"
  },
  "scripts": {
    "test": "node --test smoke-test.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "qwen",
    "qwen-code",
    "oauth",
    "authentication"
  ],
  "engines": {
    "node": ">=20"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Daltonganger/openqwencode.git"
  },
  "homepage": "https://github.com/Daltonganger/openqwencode#readme",
  "bugs": {
    "url": "https://github.com/Daltonganger/openqwencode/issues"
  },
  "license": "MIT",
  "devDependencies": {
    "@types/node": "^25.5.2"
  }
}
